use crate::aap::caps::inference_llm::infer;

struct Node;

fn classify_intent(text: &str) -> Intent {
    let lower = text.to_lowercase();
    if lower.contains("bill") || lower.contains("invoice") || lower.contains("charge") || lower.contains("payment") {
        Intent::BillingQuestion
    } else if lower.contains("error") || lower.contains("bug") || lower.contains("crash") || lower.contains("not working") || lower.contains("broken") {
        Intent::TechnicalSupport
    } else if lower.contains("account") || lower.contains("password") || lower.contains("email address") || lower.contains("username") {
        Intent::AccountChange
    } else if lower.is_empty() {
        Intent::Unknown
    } else {
        Intent::GeneralInquiry
    }
}

fn truncate_to_bytes(s: &str, max_bytes: usize) -> String {
    if s.len() <= max_bytes {
        return s.to_string();
    }
    let mut end = max_bytes;
    while end > 0 && !s.is_char_boundary(end) {
        end -= 1;
    }
    s[..end].to_string()
}

impl Guest for Node {
    fn run(message: RawMessage) -> CustomerQuery {
        let text = message.text;

        let system = "Classify the customer's intent and extract key entities. \
            Respond only with the raw question restated concisely.";
        let task = "classify";

        // Use the one permitted capability: an inference call that can influence
        // but not act. The model's output is treated as untrusted text and is
        // only ever used to help bound/clean the question field; it never
        // determines the intent, which is derived deterministically below so
        // the enum invariant always holds regardless of what the model returns.
        let model_output = infer(system, &text, task);

        let intent = classify_intent(&text);

        // Prefer the model's restated question if it's non-empty, else fall back
        // to the original text. Either way, bound the result to the contract.
        let question_source = if model_output.trim().is_empty() {
            text.clone()
        } else {
            model_output
        };
        let question = truncate_to_bytes(question_source.trim(), 512);

        CustomerQuery {
            intent,
            entities: Vec::new(),
            question,
        }
    }
}

export!(Node);
```

